export const ministries=[{name:"Ministry of Home Affairs",shortName:"MHA",category:"Home Affairs",minister:"Amit Shah",overview:"The Ministry of Home Affairs is responsible for internal security, domestic policy, and administration of the Union Territories of India.",responsibilities:["Internal security and border management","Administration of Union Territories","Coordination between Central and State governments","Management of Central Armed Police Forces","Regulation of foreigner matters and immigration"],departments:["Department of Internal Security","Department of Jammu & Kashmir Affairs","Department of Border Management","Department of Official Language","Department of States"],orgStructure:"The ministry is headed by the Union Home Secretary, with the Minister of Home Affairs overseeing all operations. It manages multiple central police organizations including CRPF, BSF, CISF, ITBP, and SSB.",established:"1947",website:"https://www.mha.gov.in"},{name:"Ministry of Defence",shortName:"MoD",category:"Defence",minister:"Rajnath Singh",overview:"The Ministry of Defence is responsible for safeguarding national security and territorial integrity of India, managing the Indian Armed Forces.",responsibilities:["Defence policy and strategy formulation","Management of Indian Armed Forces (Army, Navy, Air Force)","Defence procurement and production","Coordination with DRDO and defence research","Veterans affairs and welfare"],departments:["Department of Defence","Department of Military Affairs","Department of Defence Production","Department of Defence Research and Development","Department of Ex-Servicemen Welfare"],orgStructure:"Under the Defence Minister, the ministry operates through five departments. The Chief of Defence Staff coordinates between the three services, while each service has its own Chief.",established:"1947",website:"https://www.mod.gov.in"},{name:"Ministry of Finance",shortName:"MoF",category:"Finance",minister:"Nirmala Sitharaman",overview:"The Ministry of Finance manages India's fiscal policy, including taxation, financial legislation, financial institutions, and capital markets.",responsibilities:["Formulation of Union Budget and fiscal policy","Taxation policy and administration","Management of government finances","Regulation of financial sector","Administration of economic reforms"],departments:["Department of Economic Affairs","Department of Revenue","Department of Financial Services","Department of Public Enterprises","Department of Investment and Public Asset Management"],orgStructure:"Led by the Finance Minister with the Finance Secretary as the administrative head. The department works closely with RBI, SEBI, and other financial regulators.",established:"1947",website:"https://www.finmin.nic.in"},{name:"Ministry of External Affairs",shortName:"MEA",category:"External Affairs",minister:"Dr. S. Jaishankar",overview:"The Ministry of External Affairs handles India's foreign relations, diplomacy, and international cooperation with countries and global organizations.",responsibilities:["Foreign policy formulation and implementation","Diplomatic relations with other nations","Consular affairs and citizen services abroad","International trade and cooperation","Management of Indian embassies and consulates"],departments:["Department of East Asia","Department of Europe West","Department of Americas","Department of Africa","Department of Consular, Passport & Visa","Department of External Promotion"],orgStructure:"Headed by the External Affairs Minister with the Foreign Secretary as the senior bureaucratic head. India maintains over 190 diplomatic missions worldwide.",established:"1947",website:"https://www.mea.gov.in"},{name:"Ministry of Education",shortName:"MoE",category:"Education",minister:"Dharmendra Pradhan",overview:"The Ministry of Education is responsible for formulation and implementation of national policies on education and oversight of the education system.",responsibilities:["National education policy implementation","Higher education regulation and funding","Literacy and elementary education programs","Technical education and skill development","Scholarship and student welfare schemes"],departments:["Department of School Education & Literacy","Department of Higher Education"],orgStructure:"The ministry operates through two main departments. The Department of Higher Education manages universities and institutions like IITs, IIMs, and AIIMS, while School Education handles elementary and secondary education.",established:"1947",website:"https://www.education.gov.in"},{name:"Ministry of Health and Family Welfare",shortName:"MoHFW",category:"Health",minister:"Jagat Prakash Nadda",overview:"The Ministry of Health and Family Welfare formulates and implements health policies and programs for public health across India.",responsibilities:["National health policy and programs","Disease prevention and control","Public health infrastructure development","Medical education and research regulation","Family welfare and population control programs"],departments:["Department of Health","Department of Family Welfare","Department of Health Research"],orgStructure:"Led by the Health Minister with the Secretary (Health) as administrative head. Key organizations include AIIMS, ICMR, CDSCO, and National Health Authority.",established:"1976",website:"https://www.mohfw.gov.in"},{name:"Ministry of Railways",shortName:"MoR",category:"Transport",minister:"Ashwini Vaishnaw",overview:"The Ministry of Railways is responsible for managing Indian Railways, one of the world's largest railway networks, and formulating railway policies.",responsibilities:["Railway infrastructure development and maintenance","Passenger and freight services management","Railway safety and modernization","Budget allocation for railway projects","Coordination with Railway Board"],departments:["Finance Commission","Railway Board","Production Units","Training Institutes","Zonal Railways"],orgStructure:"Under the Railway Minister, the Railway Board serves as the apex body. Indian Railways operates through 17 zones and is one of the largest employers in the world.",established:"1951",website:"https://indianrailways.gov.in"},{name:"Ministry of Road Transport and Highways",shortName:"MoRTH",category:"Transport",minister:"Nitin Gadkari",overview:"The Ministry of Road Transport and Highways is responsible for formulation and implementation of policies for road transport and national highways.",responsibilities:["National highway construction and maintenance","Road safety policy and programs","Vehicle emission standards regulation","Inter-state transport coordination","Public transport infrastructure development"],departments:["Department of Road Transport","National Highways Authority of India (NHAI)","Central Road Research Institute","Automotive Research Association of India"],orgStructure:"The ministry works through NHAI for highway development and regional offices across states. It coordinates with state transport departments for implementation of policies.",established:"1947",website:"https://morth.nic.in"},{name:"Ministry of Agriculture and Farmers Welfare",shortName:"MoAFW",category:"Agriculture",minister:"Shivraj Singh Chouhan",overview:"The Ministry of Agriculture and Farmers Welfare is responsible for agricultural policies, programs, and farmer welfare schemes across India.",responsibilities:["Agricultural policy formulation and implementation","Farmer welfare and income support schemes","Agricultural research and extension","Crop insurance and minimum support price","International agricultural cooperation"],departments:["Department of Agriculture & Farmers Welfare","Department of Agricultural Research & Education"],orgStructure:"The ministry operates through two departments. The Indian Council of Agricultural Research (ICAR) under DARE manages agricultural research institutions across the country.",established:"1947",website:"https://agricoop.nic.in"},{name:"Ministry of Environment, Forest and Climate Change",shortName:"MoEFCC",category:"Environment",minister:"Bhupender Yadav",overview:"The Ministry of Environment, Forest and Climate Change formulates policies for environmental protection, forest conservation, and climate change mitigation.",responsibilities:["Environmental policy and regulation","Forest conservation and wildlife protection","Climate change mitigation and adaptation","Environmental impact assessment","International environmental agreements"],departments:["Department of Environment","Department of Forests","National Tiger Conservation Authority","Central Pollution Control Board"],orgStructure:"The ministry oversees key bodies including CPCB, National Green Tribunal, and wildlife institutions. It coordinates with state forest departments and international bodies like UNEP.",established:"1985",website:"https://moef.gov.in"},{name:"Ministry of Labour and Employment",shortName:"MoLE",category:"Labour",minister:"Mansukh Mandaviya",overview:"The Ministry of Labour and Employment formulates policies for worker welfare, industrial relations, and employment generation in India.",responsibilities:["Labour law formulation and reform","Worker welfare and social security","Industrial relations and dispute resolution","Employment generation programs","Skill development and training"],departments:["Labour Bureau","Employees' Provident Fund Organisation","Employees' State Insurance Corporation","Directorate General of Employment"],orgStructure:"The ministry administers 4 Labour Codes and manages EPFO and ESIC. It coordinates with state labour departments for implementation of central labour laws.",established:"1947",website:"https://labour.gov.in"},{name:"Ministry of Electronics and Information Technology",shortName:"MeitY",category:"Technology",minister:"Ashwini Vaishnaw",overview:"The Ministry of Electronics and Information Technology drives India's digital transformation, e-governance, and IT industry development.",responsibilities:["Digital India initiative implementation","IT industry promotion and regulation","E-governance and digital infrastructure","Cybersecurity and data protection","Electronics manufacturing promotion"],departments:["Department of Electronics","Department of Information Technology","National Informatics Centre","Cert-In"],orgStructure:"The ministry drives initiatives like Digital India, Make in India (electronics), and manages key IT infrastructure. It works with NASSCOM and industry bodies for IT sector growth.",established:"2007",website:"https://www.meity.gov.in"},{name:"Ministry of Power",shortName:"MoP",category:"Energy",minister:"Manohar Lal Khattar",overview:"The Ministry of Power is responsible for the administration of the Electricity Act, 2003, energy policy, and planning for the power sector.",responsibilities:["Power sector policy formulation","Electricity generation and distribution oversight","Rural electrification programs","Renewable energy integration","Power sector reform and regulation"],departments:["Central Electricity Authority","Rural Electrification Corporation","Power Finance Corporation","National Load Despatch Centre"],orgStructure:"The ministry works through Central Electricity Authority and implements schemes like Saubhagya and Ujwal DISCOM Assurance. It coordinates with CERC and SERCs for tariff regulation.",established:"1992",website:"https://power.gov.in"},{name:"Ministry of Petroleum and Natural Gas",shortName:"MoPNG",category:"Energy",minister:"Hardeep Singh Puri",overview:"The Ministry of Petroleum and Natural Gas oversees the exploration, production, and distribution of petroleum and natural gas in India.",responsibilities:["Oil and gas exploration policy","Petroleum product pricing and distribution","Natural gas pipeline infrastructure","LNG import and distribution","Downstream petroleum sector regulation"],departments:["Department of Petroleum","Petroleum Planning and Analysis Cell","Directorate General of Hydrocarbons"],orgStructure:"The ministry oversees ONGC, Indian Oil, BPCL, HPCL, and GAIL. The Directorate General of Hydrocarbons regulates upstream operations while PPAC handles data analysis.",established:"1947",website:"https://petroleum.nic.in"},{name:"Ministry of New and Renewable Energy",shortName:"MNRE",category:"Energy",minister:"Pralhad Joshi",overview:"The Ministry of New and Renewable Energy is responsible for policy and planning for new and renewable energy sources in India.",responsibilities:["Renewable energy policy formulation","Solar and wind energy program implementation","Research and development in clean energy","International cooperation on renewable energy","Rural energy access programs"],departments:["Solar Energy Corporation of India","National Institute of Solar Energy","National Institute of Wind Energy"],orgStructure:"The ministry works through SECI and national institutes for research. India targets 500 GW non-fossil fuel capacity by 2030 under the National Solar Mission.",established:"1992",website:"https://mnre.gov.in"},{name:"Ministry of Women and Child Development",shortName:"MoWCD",category:"Social Justice",minister:"Annpurna Devi",overview:"The Ministry of Women and Child Development formulates policies for the empowerment and welfare of women and children in India.",responsibilities:["Women empowerment and gender equality programs","Child protection and welfare schemes","Nutrition and ICDS program oversight","Implementation of women safety laws","National and state commission for women coordination"],departments:["Department of Women Development","Department of Child Development","Central Adoption Resource Authority","National Commission for Protection of Child Rights"],orgStructure:"The ministry implements flagship programs like Beti Bachao Beti Padhao, Sukanya Samriddhi Yojana, and manages ICDS through state-level departments.",established:"2006",website:"https://wcd.nic.in"},{name:"Ministry of Social Justice and Empowerment",shortName:"MoSJE",category:"Social Justice",minister:"Virendra Kumar",overview:"The Ministry of Social Justice and Empowerment is responsible for policy-making and programs for SC, ST, OBC, and other disadvantaged groups.",responsibilities:["SC/ST welfare and development programs","OBC and minority welfare schemes","Persons with disabilities empowerment","Drug abuse prevention programs","Scholarships and educational support for disadvantaged groups"],departments:["Department of Social Justice","Department of Empowerment of Persons with Disabilities","National Commission for Scheduled Castes","National Commission for Scheduled Tribes"],orgStructure:"The ministry administers schemes like SC/ST Sub-Plan, National Scheduled Castes Finance and Development Corporation, and coordinates with National Commissions.",established:"1947",website:"https://socialjustice.nic.in"},{name:"Ministry of Tribal Affairs",shortName:"MoTA",category:"Tribal Affairs",minister:"Jual Oram",overview:"The Ministry of Tribal Affairs is responsible for the socio-economic development of Scheduled Tribes and tribal communities in India.",responsibilities:["Tribal welfare policy formulation","Forest Rights Act implementation","Tribal education and skill development","Economic empowerment programs","Cultural heritage preservation"],departments:["Department of Tribal Affairs","Tribal Cooperative Marketing Development Federation"],orgStructure:"The ministry implements Forest Rights Act, PVTG development programs, and coordinates with TRIFED for tribal economic development.",established:"1999",website:"https://tribal.gov.in"},{name:"Ministry of Minority Affairs",shortName:"MoMA",category:"Minority Affairs",minister:"Kiren Rijiju",overview:"The Ministry of Minority Affairs formulates policies for the welfare and development of notified minority communities in India.",responsibilities:["Minority community welfare schemes","Educational empowerment programs","Skill development and livelihood support","Infrastructure development in minority areas","Anti-discrimination and protection measures"],departments:["Department of Minority Affairs","National Commission for Minorities","National Minorities Development and Finance Corporation"],orgStructure:"The ministry implements schemes like PM 15-Point Programme, Naya Savera, and Nai Udaan for minority community development.",established:"2006",website:"https://minorityaffairs.gov.in"},{name:"Ministry of Law and Justice",shortName:"MoLJ",category:"Law",minister:"Arjun Ram Meghwal",overview:"The Ministry of Law and Justice is responsible for the administration of law, legal affairs, and the legislative programme of the Government.",responsibilities:["Legal affairs administration","Legislative drafting and bill preparation","Judiciary administration and reform","Legal aid and access to justice","Intellectual property rights protection"],departments:["Department of Legal Affairs","Department of Justice","Legislative Department"],orgStructure:"The ministry works through three departments. The Department of Legal Affairs handles legal advisory, Department of Justice manages judiciary administration, and Legislative Department handles bill drafting.",established:"1947",website:"https://lawmin.nic.in"},{name:"Ministry of Corporate Affairs",shortName:"MCA",category:"Finance",minister:"Nirmala Sitharaman",overview:"The Ministry of Corporate Affairs administers the Companies Act and oversees corporate governance and regulation in India.",responsibilities:["Company law administration and enforcement","Corporate governance regulation","Insolvency and bankruptcy proceedings","Regulation of Chartered Accountants and Company Secretaries","Competition policy oversight"],departments:["Serious Fraud Investigation Office","National Company Law Tribunal","Institute of Chartered Accountants of India","Institute of Company Secretaries of India"],orgStructure:"The ministry administers the Companies Act, 2013 and operates through NCLT, NCLAT, and professional bodies like ICAI and ICSI for self-regulation.",established:"2004",website:"https://www.mca.gov.in"},{name:"Ministry of Commerce and Industry",shortName:"MoCI",category:"Commerce",minister:"Piyush Goyal",overview:"The Ministry of Commerce and Industry formulates and implements trade policies, industrial development, and foreign trade regulations.",responsibilities:["Foreign trade policy formulation","Industrial policy and ease of doing business","Special Economic Zones development","Export promotion and trade facilitation","Anti-dumping and trade remedy measures"],departments:["Department of Commerce","Department for Promotion of Industry and Internal Trade"],orgStructure:"The ministry works through DPIIT for industrial policy and Commerce Department for trade. It administers SEZs, FTP, and coordinates with DGTR for trade remedies.",established:"1947",website:"https://commerce.gov.in"},{name:"Ministry of Consumer Affairs, Food and Public Distribution",shortName:"MoCAF&PD",category:"Consumer Affairs",minister:"Prahlad Joshi",overview:"The Ministry of Consumer Affairs, Food and Public Distribution manages consumer protection, food security, and public distribution systems.",responsibilities:["Consumer protection and rights","Public distribution system (PDS) management","Food grain procurement and storage","Price stabilization of essential commodities","Weights and measures standardization"],departments:["Department of Consumer Affairs","Department of Food and Public Distribution","Central Food Safety and Standards Authority"],orgStructure:"The ministry manages PDS through FCI, protects consumers through National Consumer Helpline, and implements the National Food Security Act.",established:"1947",website:"https://dfpd.gov.in"},{name:"Ministry of Jal Shakti",shortName:"MoJS",category:"Water Resources",minister:"C.R. Patil",overview:"The Ministry of Jal Shakti is responsible for water resources management, drinking water supply, and sanitation across India.",responsibilities:["National water resources policy","Drinking water supply - Har Ghar Jal program","River basin management and flood control","Wastewater treatment and recycling","International water treaties coordination"],departments:["Department of Water Resources, River Development & Ganga Rejuvenation","Department of Drinking Water and Sanitation","Central Water Commission","Central Ground Water Board"],orgStructure:"The ministry consolidates water-related functions under one umbrella. It implements Jal Jeevan Mission and Namami Gange through dedicated authorities.",established:"2019",website:"https://jalshakti.gov.in"},{name:"Ministry of Housing and Urban Affairs",shortName:"MoHUA",category:"Urban Development",minister:"Manohar Lal Khattar",overview:"The Ministry of Housing and Urban Affairs formulates policies for urban development, housing, and municipal governance in India.",responsibilities:["Smart Cities Mission implementation","Urban housing (PMAY-Urban) programs","Municipal reform and capacity building","Metro rail and urban transport","Swachh Bharat Mission - Urban"],departments:["Department of Urban Affairs","Central Public Works Department","National Institute of Urban Affairs"],orgStructure:"The ministry implements flagship urban missions including Smart Cities, AMRUT, PMAY-U, and SBM-U. It coordinates with state urban development departments and ULBs.",established:"1952",website:"https://mohua.gov.in"},{name:"Ministry of Rural Development",shortName:"MoRD",category:"Rural Development",minister:"Shivraj Singh Chouhan",overview:"The Ministry of Rural Development is responsible for the socio-economic development of rural India through various programs and schemes.",responsibilities:["MGNREGA implementation","Rural housing (PMAY-Gramin)","Rural livelihood promotion","Pradhan Mantri Gram Sadak Yojana","Rural drinking water and sanitation"],departments:["Department of Rural Development","Department of Land Resources","National Rural Livelihood Mission"],orgStructure:"The ministry implements MGNREGA, PMAY-G, NRLM, and PMGSY through state and district-level machinery. It works with Panchayati Raj institutions for decentralized planning.",established:"1947",website:"https://rd.nic.in"},{name:"Ministry of Culture",shortName:"MoC",category:"Culture",minister:"Gajendra Singh Shekhawat",overview:"The Ministry of Culture is responsible for the preservation and promotion of India's cultural heritage, arts, and historical monuments.",responsibilities:["Cultural heritage preservation","Museum and monument management","Performing and visual arts promotion","Archaeological excavation and research","International cultural exchange programs"],departments:["Archaeological Survey of India","National Museum","Sangeet Natak Akademi","Lalit Kala Akademi","Sahitya Akademi"],orgStructure:"The ministry oversees ASI for monument preservation, National Academy of Art for performing arts, and coordinates with state culture departments for heritage management.",established:"1947",website:"https://www.indiaculture.nic.in"},{name:"Ministry of Tourism",shortName:"MoT",category:"Tourism",minister:"Gajendra Singh Shekhawat",overview:"The Ministry of Tourism formulates policies for tourism development, promotion of tourist destinations, and hospitality industry regulation.",responsibilities:["Tourism policy formulation","Destination marketing and promotion","Hospitality industry regulation","Heritage and ecotourism development","Tourist infrastructure development"],departments:["Department of Tourism","Incredible India Campaign","National Institute of Tourism and Hospitality Management"],orgStructure:"The ministry promotes tourism through Incredible India campaigns, develops tourist circuits, and coordinates with state tourism departments and private sector partners.",established:"1967",website:"https://www.incredibleindia.org"},{name:"Ministry of Youth Affairs and Sports",shortName:"MoYA&S",category:"Sports",minister:"Mansukh Mandaviya",overview:"The Ministry of Youth Affairs and Sports is responsible for promoting sports, youth development, and managing India's sporting infrastructure.",responsibilities:["Sports policy and infrastructure development","Youth empowerment and engagement programs","National games and sports event organization","Anti-doping regulation","Sports talent identification and nurturing"],departments:["Department of Youth Affairs","Department of Sports","Sports Authority of India","National Anti-Doping Agency"],orgStructure:"The ministry works through SAI for sports infrastructure, NYKS for youth engagement, and coordinates with national sports federations and Olympic Association.",established:"1982",website:"https://yas.nic.in"},{name:"Ministry of Science and Technology",shortName:"MoS&T",category:"Science",minister:"Jitendra Singh",overview:"The Ministry of Science and Technology promotes scientific research, technology development, and innovation in India.",responsibilities:["Scientific research funding and policy","Technology development and transfer","Space program oversight (ISRO coordination)","Nuclear energy development (DAE coordination)","Biotechnology promotion"],departments:["Department of Science and Technology","Department of Scientific and Industrial Research","Department of Biotechnology"],orgStructure:"The ministry funds research through DST, promotes industrial R&D through DSIR, and oversees biotechnology through DBT. It coordinates with ISRO, DAE, and DRDO.",established:"1971",website:"https://www.dst.gov.in"},{name:"Ministry of Civil Aviation",shortName:"MoCA",category:"Transport",minister:"Kinjarapu Ram Mohan Naidu",overview:"The Ministry of Civil Aviation formulates policies for the civil aviation sector, including airlines, airports, and air navigation services.",responsibilities:["Aviation policy formulation","Airport development and management","Airline regulation and safety oversight","Regional connectivity (UDAN scheme)","Air navigation services modernization"],departments:["Airports Authority of India","Directorate General of Civil Aviation","Bureau of Civil Aviation Security"],orgStructure:"The ministry works through AAI for airport management, DGCA for regulation, and BCAS for aviation security. UDAN scheme connects underserved airports.",established:"1953",website:"https://www.civilaviation.gov.in"},{name:"Ministry of Information and Broadcasting",shortName:"MoI&B",category:"Information",minister:"Ashwini Vaishnaw",overview:"The Ministry of Information and Broadcasting manages government communication, media policy, and broadcasting regulation in India.",responsibilities:["Government publicity and communication","Broadcasting and cable TV regulation","Press Accreditation and media relations","Film certification (CBFC)","Prasar Bharati oversight"],departments:["Directorate of Advertising and Visual Publicity","Central Board of Film Certification","Press Information Bureau","Prasar Bharati"],orgStructure:"The ministry manages government publicity through DAVP, certifies films through CBFC, and oversees public broadcasting through Prasar Bharati (Doordarshan & AIR).",established:"1947",website:"https://mib.gov.in"},{name:"Ministry of Panchayati Raj",shortName:"MoPR",category:"Governance",minister:"Saurabh Patel",overview:"The Ministry of Panchayati Raj is responsible for strengthening Panchayati Raj Institutions and local self-governance in rural India.",responsibilities:["Strengthening Panchayati Raj Institutions","Devolution of funds and functions","Panchayat capacity building","Rural local governance reform","State Election Commission coordination"],departments:["Department of Panchayati Raj","National Institute of Rural Development","Panchayati Raj Training Institutes"],orgStructure:"The ministry works with State Panchayati Raj Departments to ensure implementation of the 73rd Constitutional Amendment and capacity building of PRI members.",established:"1990",website:"https://panchayati raj.gov.in"},{name:"Ministry of Statistics and Programme Implementation",shortName:"MoSPI",category:"Statistics",minister:"Rao Inderjit Singh",overview:"The Ministry of Statistics and Programme Implementation manages statistical systems and monitors government flagship programmes.",responsibilities:["National statistical system coordination","GDP and economic data compilation","Programme implementation monitoring","National Statistical Commission oversight","Consumer price index management"],departments:["National Statistical Office","Central Statistical Office","National Sample Survey Office"],orgStructure:"The ministry operates through NSO for data collection, coordinates with NSC for statistical standards, and monitors infrastructure projects through MSPY.",established:"1999",website:"https://mospi.gov.in"}];export const categories=[...new Set(ministries.map(e=>e.category))].sort();